"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4381],{8613(e){e.exports=JSON.parse('{"title":"pnpm\uc73c\ub85c \uc5b4\ub5bb\uac8c npm \uacf5\uae09\ub9dd \uacf5\uaca9\uc744 \ubc29\uc5b4\ud588\ub098","date":"2025-12-16","coverUrl":"/kudzu-based-bench/assets/notion/f92299ea903ddee3.png","html":"<h1 data-notion-block-id=\\"2c6e548d-8a8e-80b9-8847-c15d696f0d40\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"2cae548d-8a8e-8034-a280-c0782647987d\\" id=\\"2cae548d-8a8e-8034-a280-c0782647987d\\">\ud68c\uc0ac\uc5d0\uc11c\ub294 pnpm\uc73c\ub85c \uc5b4\ub5bb\uac8c npm \uacf5\uae09\ub9dd \uacf5\uaca9\uc744 \ubc29\uc5b4\ud588\ub098</h2><a href=\\"https://pnpm.io/blog/2025/12/05/newsroom-npm-supply-chain-security\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pnpm.io/blog/2025/12/05/newsroom-npm-supply-chain-security</a><p data-notion-block-id=\\"2cae548d-8a8e-8047-a9ad-d27f0c4c5e61\\">\uc5b4\ub5bb\uac8c npm \uacf5\uae09\ub9dd \uacf5\uaca9\uc5d0 \ub300\ube44\ud558\ub294 \uccb4\uacc4\ub97c pnpm\uc73c\ub85c \uac16\ucd94\uc5c8\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \ubc29\uc5b4\uccb4\uacc4\uac00 \ub3cc\uc544\uac00\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub610\ub2e4\ub978 npm \uacf5\uae09\ub9dd \uacf5\uaca9(<a href=\\"https://ones-to-watch.ethansup.net/news/post/2b7e548d-8a8e-8097-bf24-f20f9aaf3bc7#2bce548d-8a8e-8077-83c9-d978dee156b9\\">\uc774\uc804 npm \uacf5\uae09\ub9dd \uacf5\uaca9 \ubd84\uc11d \uae00</a>)\uc5d0 \ub300\ube44\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc774 \uae00\uc758 \uad50\ud6c8\uacfc, \uc5ec\ub7ec \ub3c4\uad6c\ub4e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2c2e548d-8a8e-80c1-8921-e76badcb55ed\\">npm \ubcf4\uc548 \uac00\uc774\ub4dc</a>)\ub97c \uc0ac\uc6a9\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2c9e548d-8a8e-8038-9fb7-da4876b0da25\\" id=\\"2c9e548d-8a8e-8038-9fb7-da4876b0da25\\">2025\ub144\uc5d0 \uc131\ub2a5 \uce21\uc815\uc744 \uc704\ud55c \ud301</h2><a href=\\"https://www.debugbear.com/blog/2025-in-web-performance\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/2025-in-web-performance</a><p data-notion-block-id=\\"2cae548d-8a8e-8007-9014-d7e2a5fde38e\\">2025\ub144\uc5d0 \uc0c8\ub85c \ub098\uc628 \uc131\ub2a5 \uce21\uc815\uc744 \uc704\ud55c \ub3c4\uad6c\ub4e4, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \uae30\uc220\ub4e4\uc758 \ubc1c\uc804\uc774 \uc788\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. 2024\ub144, 2023\ub144\u2026 \uc774\uc804\uc758 \uac83\ub4e4\ub3c4 \uc18c\uac1c\ud558\ubbc0\ub85c \ubcf4\uc2dc\ub294\uac83\uc744 \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"2c6e548d-8a8e-8089-8b50-c97a467b5e5e\\" id=\\"2c6e548d-8a8e-8089-8b50-c97a467b5e5e\\">Next.js\uc758 \ub300\ud56d\ub9c8\u2026.?</h2><a href=\\"https://ondrejvelisek.github.io/tanstack-start-new-competitor-to-nextjs/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ondrejvelisek.github.io/tanstack-start-new-competitor-to-nextjs/</a><p data-notion-block-id=\\"2c6e548d-8a8e-805d-893e-e5a182fd7d37\\">Next.js\uc758 \ub300\ud56d\ub9c8\ub85c\uc11c, Tanstack start\ub294 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uc5b4\ub5a4 \ubd80\ubd84\uc5d0 \uc9d1\uc911\ud588\ub294\uc9c0 \ube44\uad50\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. RSC\uac00 \ucd5c\uadfc \ub9ce\uc740 \uc774\uc288\uac00 \uc788\uae34 \ud588\uc5b4\ub3c4 \ube4c\ub4dc \uacb0\uacfc\ubb3c\uc744 \uc904\uc774\ub294\ub370 \uc544\uc8fc \uc88b\uc740 \uc5ed\ud560\uc744 \ud574\uc8fc\uace0 \uc788\uace0, \ub610\ud55c \uadf8\uc5d0 \ubabb\uc9c0 \uc54a\uac8c tanstack/query\uac00 \ubb34\uac81\ub2e4\ub77c\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub294 \ube44\uad50 \uae00\uc774\uc600\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2cae548d-8a8e-805a-8e05-f5981cbbaf44\\" id=\\"2cae548d-8a8e-805a-8e05-f5981cbbaf44\\">\uc5b4\ub5bb\uac8c \ubc88\ub4e4 \uc0ac\uc774\uc988\ub97c \uc904\uc77c\uae4c</h2><a href=\\"https://www.developerway.com/posts/bundle-size-investigation\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/bundle-size-investigation</a><p data-notion-block-id=\\"2cae548d-8a8e-8084-a603-f48d23c6c331\\">Bundle Size Analyzer\ub97c \ubcf4\uace0 \ud310\ub2e8\ud558\ub294 \ubc29\ubc95, \uadf8\ub9ac\uace0 Tree shaking\uc5d0 \ub300\ud55c \uae30\ubcf8\uc801\uc778 \uac1c\ub150(<a href=\\"https://ones-to-watch.ethansup.net/news/post/e118a44c-46de-44b7-9492-998633298d32#a0608cf9-07a8-4413-95e5-f535e3811bff\\">\ub354 \uae4a\uc740 \uac1c\ub150\uc740 \ub2e4\uc74c\uc744 \ucc38\uc870\ud558\uc138\uc694</a>), \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uc9c4\ud589\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \uc790\uc2e0\uc758 \uc6f9\uc0ac\uc774\ud2b8\ub97c \uc904\uc778 \ud6c4\uae30\uc5d0 \uac00\uae5d\uc9c0\ub9cc, \uac1c\ub150\uc744 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\uace0, \ud310\ub2e8\ud558\ub294 \ubc29\uc2dd\uc740 \ubc30\uc6b8\ub9cc\ud55c \ud3ec\uc778\ud2b8\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2cae548d-8a8e-80c6-9af0-e6e9b066f968\\" id=\\"2cae548d-8a8e-80c6-9af0-e6e9b066f968\\">TypeScript, \ub354 \ub113\uac8c \uc0ac\uc6a9\ud558\uae30</h2><a href=\\"https://marmelab.com/blog/2025/12/04/typescript-type-as-a-programming-language.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marmelab.com/blog/2025/12/04/typescript-type-as-a-programming-language.html</a><p data-notion-block-id=\\"2cae548d-8a8e-8080-b87a-ca92e69cb91e\\">TypeScript\ub97c \ub2e8\uc21c\ud558\uac8c <code>interface</code>\uc640 \ud0c0\uc785\ub9cc \uc0ac\uc6a9\ud558\uae30 \uc26c\uc6b4\ub370, \uc774\ub97c \ub354 \ubc1c\uc804\uc2dc\ucf1c\uc11c \uc5b4\ub5a4 \uac83\uc744 \ud560 \uc218 \uc788\uace0, \uc5b4\ub5a4 \uacf3\uc5d0 \uc0ac\uc6a9\ud558\ub294\uc9c0 \uc18c\uac1c\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 Type\uc744 \uc798 \uc0ac\uc6a9\ud558\uace0 \uc2f6\ub2e4\uba74, <code>as</code>\ub300\uc2e0 <code>satiesfies</code>\ub97c \uad8c\uc7a5\ud558\uace0, <a href=\\"https://www.totaltypescript.com/ts-reset\\">ts-reset</a>\uc744 \uc801\uc6a9\ud574\ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uc2dc\ub3c4\uc77c \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2c6e548d-8a8e-8056-aaaf-cb72022ef2b7\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"2cae548d-8a8e-8075-b6e0-dc472ad1bc8e\\" id=\\"2cae548d-8a8e-8075-b6e0-dc472ad1bc8e\\">RSC \uad00\ub828 \ubcf4\uc548 \ubb38\uc81c (2)</h2><a href=\\"https://react.dev/blog/2025/12/11/denial-of-service-and-source-code-exposure-in-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2025/12/11/denial-of-service-and-source-code-exposure-in-react-server-components</a><p data-notion-block-id=\\"2cae548d-8a8e-8074-aec6-e69000731677\\">\ub274\uc2a4\ub808\ud130\ub85c\uc11c \uc804\ub2ec\ub4dc\ub9ac\ub294 \uac83\uc774 \ub2a6\uc5c8\uc9c0\ub9cc, RSC\uc5d0\uc11c\uc758 \ubcf4\uc548\ubb38\uc81c\uac00 \uc0c8\ub85c \ub098\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2cae548d-8a8e-8009-890a-f38c915b2619\\" id=\\"2cae548d-8a8e-8009-890a-f38c915b2619\\">React 19.2\ub294 INP\ub97c \ucd5c\uc801\ud654\ud558\ub294\ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4</h2><a href=\\"https://calendar.perfplanet.com/2025/react-19-2-further-advances-inp-optimization/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://calendar.perfplanet.com/2025/react-19-2-further-advances-inp-optimization/</a><h2 data-notion-block-id=\\"2c6e548d-8a8e-8012-ab7a-ccc0e39de923\\" id=\\"2c6e548d-8a8e-8012-ab7a-ccc0e39de923\\"><code>useEffectEvent</code>, \uc5b4\ub5bb\uac8c \uc368\uc57c \ud558\ub098?</h2><a href=\\"https://slicker.me/react/useEffectEvent.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://slicker.me/react/useEffectEvent.html</a><h2 data-notion-block-id=\\"2cae548d-8a8e-80d6-8d6a-dab7880fee2f\\" id=\\"2cae548d-8a8e-80d6-8d6a-dab7880fee2f\\">2025\ub144, CSS\uc5d0\uc11c\ub294 \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub098</h2><a href=\\"https://chrome.dev/css-wrapped-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://chrome.dev/css-wrapped-2025/</a><h2 data-notion-block-id=\\"2cae548d-8a8e-8064-b128-c9e342229b4e\\" id=\\"2cae548d-8a8e-8064-b128-c9e342229b4e\\"><code>postMessage</code>\uc5d0\ub294 \ubb34\uc2a8 \ubb38\uc81c\uac00 \uc788\ub098</h2><a href=\\"https://blogs.windows.com/msedgedev/2025/12/09/making-complex-web-apps-faster/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blogs.windows.com/msedgedev/2025/12/09/making-complex-web-apps-faster/</a><p data-notion-block-id=\\"2c9e548d-8a8e-8042-82eb-d4fa199213de\\">\uc0c8\ub85c\uc6b4 delayed Message Timing API \uc81c\uc548\uc5d0 \uad00\ud55c \uae00\ub3c4 \uc788\uc9c0\ub9cc, \ud604\uc7ac \uc0c1\ud0dc\uc5d0\uc11c Messaging API\uac00 \uc5b4\ub5a4 \ubb38\uc81c\ub97c \uac16\uace0 \uc788\ub294\uc9c0 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2c9e548d-8a8e-8053-95d0-d5628c95604d\\" id=\\"2c9e548d-8a8e-8053-95d0-d5628c95604d\\">children props\ub85c \uc7ac\ub80c\ub354\ub9c1 \ubc29\uc9c0\ud558\uae30</h2><a href=\\"https://shramko.dev/blog/react-elements-children\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shramko.dev/blog/react-elements-children</a><h2 data-notion-block-id=\\"2cae548d-8a8e-8043-8d59-e2c8bf578287\\" id=\\"2cae548d-8a8e-8043-8d59-e2c8bf578287\\">shadcn/ui\ub97c \uc720\uc5f0\ud558\uac8c \ub9cc\ub4e4\uae30</h2><a href=\\"https://ui.shadcn.com/create\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.shadcn.com/create</a><p data-notion-block-id=\\"2c9e548d-8a8e-8080-a57d-e1b8d4d7915d\\">shadcn/ui\uac00 base-ui \uc9c0\uc6d0\uacfc \ub2e4\uc591\ud55c \uc2a4\ud0c0\uc77c \uc9c0\uc6d0\uc744 \ucd94\uac00\ud558\uba74\uc11c, \ub2e4\uc591\ud55c \uc2a4\ud0c0\uc77c\uc744 \ubc14\ub85c \uc801\uc6a9\ud574\ubcf4\uace0 \uc2dc\ud5d8\ud574\ubcfc \uc218 \uc788\ub294 shadcn create \ud398\uc774\uc9c0\ub97c \ub9cc\ub4e4\uc5c8\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"2c6e548d-8a8e-8070-9246-c8b698f19078\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://reactnative.dev/blog/2025/12/10/react-native-0.83\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2025/12/10/react-native-0.83</a><p data-notion-block-id=\\"2c6e548d-8a8e-8035-9647-ea2bfb9bb719\\">React 19.2\uc640 devtools \uae30\ub2a5\uc774 \ucd94\uac00\ub41c React Native \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://valibot.dev/blog/valibot-v1.2-release-notes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/valibot-v1.2-release-notes</a><p data-notion-block-id=\\"2cae548d-8a8e-80eb-be42-ff6b1ebe0e31\\">\uc790\ub3d9 \ud615\ubcc0\ud658\uacfc AI \ubb38\uc11c \uc9c0\uc6d0\uc744 \ucd94\uac00\ud55c valibot 1.2 \ucd9c\uc2dc \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/poppinss/ts-exec\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/poppinss/ts-exec</a><p data-notion-block-id=\\"2cbe548d-8a8e-801b-b7cf-f709a08bea35\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/17ee548d-8a8e-8045-8a26-f5dfa6d03856#17ee548d-8a8e-8006-ba30-fc20a932c3a8\\">type stripping\uc744 \uae30\ubc18</a>\uc73c\ub85c\ub9cc\ub4e0 <code>tsx</code>, <code>ts-node</code> \ub300\uccb4\uc81c\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"2cbe548d-8a8e-80fa-aec8-e9c4d58a437a\\"></p>"}')}}]);